-- [[ GÀ GAMING SYSTEM LEVEL MAX ]]
-- BẢO MẬT TỐI THƯỢNG - BYPASS CRASH EXECUTOR 100%

local input_key = _G.Key or getgenv().Key
local correct_key = "GA_13_06_2026"

if input_key ~= correct_key then
    warn("❌ Gà Gaming: Sai Key hoặc Key đã hết hạn hôm nay! Hãy lấy key mới.")
    return
end

local _hex = ""
local _buffer = {}
local _idx = 0

-- Bộ giải mã siêu tốc sử dụng bộ đệm bảng hệ thống
for _byte in string.gmatch(_hex, "..") do
    _idx = _idx + 1
    _buffer[_idx] = string.char(tonumber(_byte, 16))
end

local _source = table.concat(_buffer)
local run, err = loadstring(_source)

if run then
    run()
else
    warn("❌ Lỗi kích hoạt hệ thống LV MAX: " .. tostring(err))
end
